def decode_cyclic(s: str) -> str:
    def cycle_decompress(group):
        while True:
            yield group
            group = group[-1] + group[:-1]

    result = [''] * (len(s) // 3)
    for i, group in enumerate(cycle_decompress(s)):
        result[i] = group

    return ''.join(result)
